/**
 * Routes.
 * @module routes
 */

import { App } from '@plone/volto/components';
import { defaultRoutes } from '@plone/volto/routes';

const routes = [
  {
    path: '/',
    component: App,
    routes: [
      ...defaultRoutes,
    ],
  },
];

export default routes;
